INSERT INTO legal_pages (tenant_id, page_type, title_nl, content_nl, is_published, is_auto_generated) VALUES (t, 'contact', 'Contact', '<h1>Contact</h1><p>Bistro Mirabelle is een demowinkel van SellQo. Naam, adres en producten zijn verzonnen.</p><p>Vragen over SellQo of over deze demo? Mail naar <a href="mailto:info@sellqo.app">info@sellqo.app</a>.</p>', true, false);
INSERT INTO legal_pages (tenant_id, page_type, title_nl, content_nl, is_published, is_auto_generated) VALUES (t, 'terms', 'Algemene voorwaarden', '<h1>Algemene voorwaarden</h1><p>Bistro Mirabelle is een demowinkel van SellQo. Er wordt niets bereid, geleverd of aangerekend. Bestellingen worden na 14 dagen automatisch gewist.</p><p>Contact: <a href="mailto:info@sellqo.app">info@sellqo.app</a>.</p>', true, false);
INSERT INTO legal_pages (tenant_id, page_type, title_nl, content_nl, is_published, is_auto_generated) VALUES (t, 'privacy', 'Privacybeleid', '<h1>Privacybeleid</h1><p>Dit is een demowinkel van SellQo. Wat je hier invult, gebruiken we enkel om de demo te laten werken; het wordt na 14 dagen gewist. Gebruik bij voorkeur een testadres.</p>', true, false);
INSERT INTO ops.demo_shops (tenant_id, note) VALUES (t, 'Bistro Mirabelle');
INSERT INTO ops.demo_stock (tenant_id, product_id, variant_id, stock) SELECT tenant_id, id, null, stock FROM products WHERE tenant_id = t AND track_inventory UNION ALL SELECT tenant_id, product_id, id, stock FROM product_variants WHERE tenant_id = t;
